public with sharing class OverdueInvoiceBatch implements Database.Batchable<sObject>, Database.Stateful {

    // Instance totals – persisted across chunks/finish for a real batch run (Database.Stateful).
    private Integer instanceUpdated = 0;
    private Integer instanceFailed = 0;
    private Decimal instanceAmount = 0;

    // Static totals – let finish() see every chunk when start/execute/finish are invoked
    // directly (in the same transaction), even if a different instance is used.
    private static Integer staticUpdated = 0;
    private static Integer staticFailed = 0;
    private static Decimal staticAmount = 0;

    public OverdueInvoiceBatch() {
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator(
            'SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c ' +
            'FROM FB_Invoice__c ' +
            'WHERE Status__c = \'Open\' AND Due_Date__c < TODAY'
        );
    }

    public void execute(Database.BatchableContext bc, List<FB_Invoice__c> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        List<FB_Invoice__c> toUpdate = new List<FB_Invoice__c>();
        for (FB_Invoice__c invoice : scope) {
            if (invoice == null) {
                continue;
            }
            invoice.Status__c = 'Overdue';
            toUpdate.add(invoice);
        }

        if (toUpdate.isEmpty()) {
            return;
        }

        Database.SaveResult[] results;
        try {
            // allOrNone = false : one bad row (e.g. the validation rule) must not roll back
            // the rest of the chunk.
            results = Database.update(toUpdate, false);
        } catch (Exception e) {
            // Nothing could be saved for this chunk; record every row as failed and keep going.
            instanceFailed += toUpdate.size();
            staticFailed += toUpdate.size();
            return;
        }

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (sr.isSuccess()) {
                instanceUpdated++;
                staticUpdated++;

                Decimal amount = toUpdate[i].Amount__c;
                if (amount != null) {
                    instanceAmount += amount;
                    staticAmount += amount;
                }
            } else {
                instanceFailed++;
                staticFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        // When the job ran through Database.executeBatch, the instance totals survive thanks to
        // Database.Stateful (the statics of a new transaction are empty).
        // When start/execute/finish are called directly, fall back to the static running totals
        // in case finish() is invoked on a different instance than execute() was.
        Boolean useInstanceTotals = (instanceUpdated != 0 || instanceFailed != 0);

        Integer recordsUpdated = useInstanceTotals ? instanceUpdated : staticUpdated;
        Integer recordsFailed = useInstanceTotals ? instanceFailed : staticFailed;
        Decimal overdueAmount = useInstanceTotals ? instanceAmount : staticAmount;

        FB_Job_Summary__c summary = new FB_Job_Summary__c(
            Job_Name__c = 'OverdueInvoiceBatch',
            Records_Updated__c = recordsUpdated,
            Records_Failed__c = recordsFailed,
            Overdue_Amount__c = overdueAmount
        );
        insert summary;
    }
}
