/**
 * Bulk-safe Contact trigger.
 *
 * The trigger itself performs no SOQL and no DML - it only delegates to
 * ContactTriggerHandler, so all limits-consuming logic lives in one testable class.
 *
 * Budget for a single execution of up to 200 Contacts (before + after together):
 *   before insert / before update -> at most 1 SOQL, 0 DML
 *   after insert                  -> at most 1 SOQL, 1  DML
 *   total                         -> at most 2 SOQL, 1 DML
 */
trigger ContactTrigger on Contact (before insert, before update, after insert) {

    if (Trigger.isBefore && Trigger.isInsert) {
        ContactTriggerHandler.onBeforeInsert(Trigger.new);

    } else if (Trigger.isBefore && Trigger.isUpdate) {
        ContactTriggerHandler.onBeforeUpdate(Trigger.new);

    } else if (Trigger.isAfter && Trigger.isInsert) {
        ContactTriggerHandler.onAfterInsert(Trigger.new);
    }
}
