/**
 * Handler for the Contact trigger.
 *
 * Bulk-safe: all Account reads are collected into a single SOQL query per context
 * and all Account writes are collected into a single DML statement.
 *
 * Declared `without sharing` on purpose: Apex triggers run in system mode and
 * ignore sharing, so the original inline queries in the trigger could see every
 * Account. Keeping the handler without sharing preserves that exact behaviour.
 */
public without sharing class ContactTriggerHandler {

    /**
     * Before insert: default MailingCountry (and LeadSource) from the Account.
     *
     * @param newContacts the Contacts in Trigger.new
     */
    public static void onBeforeInsert(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, true);
    }

    /**
     * Before update: default MailingCountry from the Account.
     * (LeadSource is only defaulted on insert, exactly as in the original trigger.)
     *
     * @param newContacts the Contacts in Trigger.new
     */
    public static void onBeforeUpdate(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, false);
    }

    /**
     * After insert: if the Contact has a phone and the Account has none,
     * copy the Contact phone onto the Account. When several Contacts of the same
     * Account qualify, the first one in trigger order wins - because each Account
     * is only mutated in memory once, later Contacts see a non-blank phone and skip.
     *
     * Uses at most 1 SOQL query and at most 1 DML statement.
     *
     * @param newContacts the Contacts in Trigger.new
     */
    public static void onAfterInsert(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // 1 SOQL query for every qualifying Account.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            // Blank guard: an Account already carrying a phone (from the database or
            // set earlier in this loop by a previous Contact) is never overwritten.
            if (a == null || String.isNotBlank(a.Phone)) {
                continue;
            }
            a.Phone = c.Phone;
            accountsToUpdate.put(a.Id, a);
        }

        // 1 DML statement, and only if something actually changed.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }

    /**
     * Shared before-context logic: default the Contact's MailingCountry from the
     * Account's BillingCountry, and (insert only) the LeadSource from AccountSource.
     *
     * Uses at most 1 SOQL query and no DML.
     *
     * @param newContacts the Contacts in Trigger.new
     * @param isInsert    true when running in the before insert context
     */
    private static void applyAccountDefaults(List<Contact> newContacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // 1 SOQL query for every referenced Account.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }
}
