/**
 * Service class that groups Contacts of a set of Accounts by the
 * (lower-cased) domain part of their e-mail address.
 *
 * The class is declared `with sharing` so that the running user's sharing
 * rules are always respected. All work is done in a single SOQL query, so the
 * method is bulk-safe regardless of how many accounts are passed in.
 */
public with sharing class ContactDomainService {

    /**
     * Groups the contacts of the given accounts by the lower-cased domain of
     * their e-mail address.
     *
     * @param accountIds Ids of the accounts whose contacts should be grouped.
     *                   A null or empty set yields an empty map (no query is run).
     * @return Map keyed by the lower-cased e-mail domain (e.g. `example.com`)
     *         holding the matching contacts. Contacts without a usable e-mail
     *         address are left out. Every returned contact has `Id`, `Email`
     *         and `AccountId` populated.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Single bulk-safe query; `with sharing` on the class keeps sharing rules.
        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
            ORDER BY Id
        ];

        for (Contact contact : contacts) {
            String domain = domainOf(contact.Email);
            if (String.isBlank(domain)) {
                // No usable e-mail / no domain part -> leave the contact out.
                continue;
            }
            if (!contactsByDomain.containsKey(domain)) {
                contactsByDomain.put(domain, new List<Contact>());
            }
            contactsByDomain.get(domain).add(contact);
        }

        return contactsByDomain;
    }

    /**
     * Extracts the lower-cased domain part of an e-mail address.
     *
     * @param email the e-mail address, may be null or blank
     * @return the lower-cased domain (e.g. `example.com` for `Jane@Example.COM`)
     *         or null when the address has no usable domain part
     */
    private static String domainOf(String email) {
        if (String.isBlank(email)) {
            return null;
        }

        String normalized = email.trim();
        // Use the last '@' so the domain can never contain an '@' itself.
        Integer atSign = normalized.lastIndexOf('@');
        if (atSign < 0 || atSign == normalized.length() - 1) {
            return null;
        }

        String domain = normalized.substring(atSign + 1).trim().toLowerCase();
        return String.isBlank(domain) ? null : domain;
    }
}
