public with sharing class ContactLookupAction {

    private ContactLookupAction() {
        // Utility class – not instantiable.
    }

    /**
     * Finds an existing Contact by email address.
     *
     * Executes at most one SOQL query per invocation, returns exactly one Result
     * per Request (in the same order), matches emails case-insensitively ignoring
     * surrounding whitespace, and respects the running user's sharing rules.
     */
    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing Contact whose email matches the given address (case-insensitive, trimmed). Returns the earliest-created match.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // ------------------------------------------------------------------
        // 1. Normalize every input up front and collect the lookup keys.
        // ------------------------------------------------------------------
        List<String> requestKeys = new List<String>();   // one normalized key per request (same order/size)
        Set<String> lookupKeys = new Set<String>();      // distinct, non-blank keys to query

        for (Integer i = 0; i < requests.size(); i++) {
            Request req = requests[i];
            String raw = (req == null) ? null : req.email;
            String key = (raw == null) ? '' : raw.trim().toLowerCase();

            requestKeys.add(key);

            if (String.isNotBlank(key)) {
                lookupKeys.add(key);
            }
        }

        // ------------------------------------------------------------------
        // 2. Single SOQL query: fetch matches for all requested emails at once,
        //    ordered by CreatedDate so the earliest match wins per email.
        // ------------------------------------------------------------------
        Map<String, Contact> earliestMatchByKey = new Map<String, Contact>();

        if (!lookupKeys.isEmpty()) {
            List<Contact> matches = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :lookupKeys
                ORDER BY CreatedDate ASC
            ];

            for (Contact c : matches) {
                if (c.Email == null) {
                    continue;
                }
                String key = c.Email.trim().toLowerCase();
                if (!earliestMatchByKey.containsKey(key)) {
                    earliestMatchByKey.put(key, c);
                }
            }
        }

        // ------------------------------------------------------------------
        // 3. Build exactly one Result per Request, preserving input order.
        // ------------------------------------------------------------------
        for (String key : requestKeys) {
            Result result = new Result();
            Contact match = String.isBlank(key) ? null : earliestMatchByKey.get(key);

            if (match == null) {
                result.found = false;
                result.contactId = null;
            } else {
                result.found = true;
                result.contactId = match.Id;
            }
            results.add(result);
        }

        return results;
    }

    /** Input parameters for the invocable action. */
    public class Request {
        @InvocableVariable(
            label='Email'
            description='Email address of the Contact to find. Leading/trailing spaces are ignored and matching is case-insensitive.'
            required=true
        )
        public String email;
    }

    /** Output returned to the Flow for each request. */
    public class Result {
        @InvocableVariable(
            label='Contact Id'
            description='Id of the matching Contact, or null if no match was found.'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True when a Contact with the requested email was found.'
        )
        public Boolean found;
    }
}
