/**
 * Tests for ShippingCostCalculator.
 *
 * Coverage targets (each chosen so a subtle mutation of the production class
 * breaks at least one assertion):
 *   - weight validation (null / zero / negative / tiny positive)
 *   - zone validation (null, empty, unknown) and the fact that it happens
 *     before the free-shipping shortcut
 *   - case-insensitive zone matching
 *   - every base-price tier INCLUDING its exact upper boundary and the first
 *     value above it (off-by-one detection)
 *   - the per-started-kilogram surcharge above 20 kg (ceiling detection)
 *   - each zone multiplier constant
 *   - the express uplift constant, plus explicit false and null flags
 *   - free-shipping conditions (zone, express, exact 100.00 threshold, null value)
 *   - HALF_UP rounding at a .xx5 boundary
 */
@isTest
private class ShippingCostCalculatorTest {

    /* ------------------------------------------------------------------ */
    /* Helpers                                                            */
    /* ------------------------------------------------------------------ */

    private static void assertQuote(Decimal weightKg, String zone, Boolean express,
                                    Decimal orderValue, Decimal expected, String label) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        System.assertEquals(expected, actual,
            label + ': expected ' + expected + ' but got ' + actual);
    }

    private static void assertThrows(Decimal weightKg, String zone, Boolean express,
                                     Decimal orderValue, String label) {
        Boolean thrown = false;
        try {
            ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        } catch (ShippingCostCalculator.ShippingException e) {
            thrown = true;
        }
        System.assert(thrown, label + ': expected a ShippingException to be thrown');
    }

    /* ------------------------------------------------------------------ */
    /* Weight validation                                                  */
    /* ------------------------------------------------------------------ */

    @isTest
    static void nullWeightThrows() {
        assertThrows(null, 'DOMESTIC', false, null, 'null weight');
        assertThrows(null, null, null, null, 'null weight and null zone');
    }

    @isTest
    static void zeroWeightThrows() {
        assertThrows(0, 'DOMESTIC', false, null, 'zero weight');
        assertThrows(0.00, 'EU', true, 100, 'zero weight as decimal');
    }

    @isTest
    static void negativeWeightThrows() {
        assertThrows(-1, 'DOMESTIC', false, null, 'negative weight');
        assertThrows(-0.001, 'WORLD', false, null, 'tiny negative weight');
    }

    @isTest
    static void tinyPositiveWeightIsAccepted() {
        // Anything strictly greater than 0 is valid and lands in the 1 kg tier.
        assertQuote(0.001, 'DOMESTIC', false, null, 5.00, '0.001 kg');
        assertQuote(0.5, 'DOMESTIC', false, null, 5.00, '0.5 kg');
    }

    /* ------------------------------------------------------------------ */
    /* Zone validation                                                    */
    /* ------------------------------------------------------------------ */

    @isTest
    static void nullZoneThrows() {
        assertThrows(1, null, false, null, 'null zone');
        assertThrows(1, null, false, 100, 'null zone with free-shipping value');
    }

    @isTest
    static void emptyZoneThrows() {
        assertThrows(1, '', false, null, 'empty zone');
    }

    @isTest
    static void unknownZoneThrows() {
        assertThrows(1, 'MARS', false, null, 'unknown zone');
        assertThrows(1, 'domestic ', false, null, 'zone with trailing space');
        assertThrows(1, ' EU', false, null, 'zone with leading space');
    }

    @isTest
    static void zoneIsCheckedBeforeFreeShipping() {
        // The free-shipping shortcut must not swallow an invalid zone.
        assertThrows(1, 'MARS', false, 100, 'unknown zone with orderValue 100');
        assertThrows(1, null, false, 100, 'null zone with orderValue 100');
    }

    @isTest
    static void weightIsCheckedBeforeZone() {
        assertThrows(0, 'MARS', false, null, 'zero weight and unknown zone');
    }

    @isTest
    static void zonesAreCaseInsensitive() {
        assertQuote(1, 'domestic', false, null, 5.00, 'lower-case domestic');
        assertQuote(1, 'eu', false, null, 7.00, 'lower-case eu');
        assertQuote(1, 'world', false, null, 11.00, 'lower-case world');
        assertQuote(1, 'DoMeStIc', false, null, 5.00, 'mixed-case domestic');
        assertQuote(5, 'eU', false, null, 13.30, 'mixed-case eu');
        assertQuote(20, 'WoRlD', false, null, 39.60, 'mixed-case world');
        // Free shipping must also honour a lower-case zone.
        assertQuote(1, 'domestic', false, 100, 0.00, 'lower-case domestic free shipping');
    }

