    @isTest
    static void firstTierIsFiveUpToAndIncludingOneKg() {
        assertQuote(1, 'DOMESTIC', false, null, 5.00, 'exactly 1 kg');
        // Just above the boundary must fall into the next tier.
        assertQuote(1.0001, 'DOMESTIC', false, null, 9.50, 'just above 1 kg');
        assertQuote(1.5, 'DOMESTIC', false, null, 9.50, '1.5 kg');
    }

    @isTest
