        assertQuote(2, 'DOMESTIC', false, null, 9.50, '2 kg');
        assertQuote(5, 'DOMESTIC', false, null, 9.50, 'exactly 5 kg');
        // Just above the boundary must fall into the next tier.
        assertQuote(5.0001, 'DOMESTIC', false, null, 18.00, 'just above 5 kg');
        assertQuote(7, 'DOMESTIC', false, null, 18.00, '7 kg');
