/**
 * Tests for OpportunityTrigger and OpportunityWonHandler.
 *
 * Documented behaviour covered:
 *  - An opportunity that is inserted with StageName 'Closed Won' is "newly won": NextStep is set
 *    to 'Handover to Customer Success' before the record is saved, exactly one Task
 *    ('Customer kick-off', WhatId = the opportunity, OwnerId = the opportunity owner,
 *    ActivityDate = CloseDate + 7 days, Priority 'High') is created and the account (if any) is
 *    re-rated 'Hot'.
 *  - An opportunity updated from any other stage to 'Closed Won' gets the same treatment.
 *  - Every other insert or update (insert of a non-won opportunity, an edit to an opportunity that
 *    was already won, an update that leaves Closed Won) changes nothing.
 *  - Accounts already rated 'Hot' are not updated again.
 *  - Bulk safety: at most one SOQL query (and therefore at most two DML statements: tasks +
 *    accounts) per trigger execution for up to 200 records.
 */
@IsTest
private class OpportunityWonHandlerTest {

    private static final String WON = 'Closed Won';
    private static final String LOST = 'Closed Lost';
    private static final String PROSPECTING = 'Prospecting';
    private static final String HANDOVER = 'Handover to Customer Success';
    private static final String KICK_OFF = 'Customer kick-off';
    private static final String HIGH = 'High';
    private static final String HOT = 'Hot';
    private static final String WARM = 'Warm';
    private static final String COLD = 'Cold';

    /* ------------------------------------------------------------------ */
    /* helpers                                                            */
    /* ------------------------------------------------------------------ */

    private static Account makeAccount(String rating) {
        return new Account(Name = 'Test Account', Rating = rating);
    }

    private static Opportunity makeOpportunity(String name, String stage, Date closeDate, Id accountId) {
        Opportunity o = new Opportunity(Name = name, StageName = stage, CloseDate = closeDate);
        if (accountId != null) {
            o.AccountId = accountId;
        }
        return o;
    }

    private static Set<Id> idsOf(List<Opportunity> opps) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity o : opps) {
            ids.add(o.Id);
        }
        return ids;
    }

    private static List<Task> tasksFor(Set<Id> oppIds) {
        return [
            SELECT Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId IN :oppIds
        ];
    }

    private static String nextStepOf(Id oppId) {
        return [SELECT NextStep FROM Opportunity WHERE Id = :oppId].NextStep;
    }

    private static String ratingOf(Id accountId) {
        return [SELECT Rating FROM Account WHERE Id = :accountId].Rating;
    }

    /* ------------------------------------------------------------------ */
    /* insert as Closed Won                                               */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void insertClosedWonAppliesFullHandover() {
        Account acct = makeAccount(WARM);
        insert acct;

        Opportunity o = makeOpportunity('Won on insert', WON, Date.newInstance(2025, 1, 31), acct.Id);
        o.NextStep = 'To be replaced';

        insert o;

        Opportunity saved = [SELECT NextStep, OwnerId FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(HANDOVER, saved.NextStep,
            'An opportunity inserted with StageName Closed Won must get NextStep "' + HANDOVER + '".');

        List<Task> tasks = tasksFor(new Set<Id>{ o.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        Task t = tasks[0];
        System.assertEquals(KICK_OFF, t.Subject, 'The task subject must be "Customer kick-off".');
        System.assertEquals(o.Id, t.WhatId, 'The task must be linked to the opportunity.');
        System.assertEquals(saved.OwnerId, t.OwnerId, 'The task must be owned by the opportunity owner.');
        System.assertEquals(HIGH, t.Priority, 'The task priority must be High.');
        System.assertEquals(Date.newInstance(2025, 2, 7), t.ActivityDate,
            'ActivityDate must be CloseDate + 7 days, including across a month boundary.');

        System.assertEquals(HOT, ratingOf(acct.Id), 'The account must be re-rated Hot.');
    }

    @IsTest
    static void insertClosedWonWithoutAccountStillGetsHandover() {
        Opportunity o = makeOpportunity('Won on insert, no account', WON, Date.newInstance(2025, 9, 9), null);

        insert o;

        System.assertEquals(HANDOVER, nextStepOf(o.Id),
            'NextStep must be set even when the opportunity has no account.');
        List<Task> tasks = tasksFor(new Set<Id>{ o.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        System.assertEquals(Date.newInstance(2025, 9, 16), tasks[0].ActivityDate,
            'ActivityDate must be CloseDate + 7 days.');
        System.assertEquals(o.Id, tasks[0].WhatId, 'The task must be linked to the opportunity.');
        System.assertEquals(HIGH, tasks[0].Priority, 'The task priority must be High.');
    }

    @IsTest
    static void taskIsOwnedByTheOpportunityOwner() {
        Profile p = [SELECT Id FROM Profile WHERE UserType = 'Standard' LIMIT 1];
        User u = new User(
            Alias = 'handover',
            Email = 'handover.owner@example.test',
            EmailEncodingKey = 'UTF-8',
            LastName = 'Handover Owner',
            LanguageLocaleKey = 'en_US',
            LocaleSidKey = 'en_US',
            ProfileId = p.Id,
            TimeZoneSidKey = 'America/Los_Angeles',
            Username = 'handover.' + EncodingUtil.convertToHex(Crypto.generateAesKey(128)).substring(0, 12)
                + '@example.test'
        );
        insert u;

        Opportunity o = makeOpportunity('Owned by somebody else', WON, Date.newInstance(2025, 5, 16), null);
        o.OwnerId = u.Id;
        insert o;

        List<Task> tasks = tasksFor(new Set<Id>{ o.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        System.assertEquals(u.Id, tasks[0].OwnerId,
            'The kick-off task must be owned by the opportunity owner, not by the running user.');
        System.assertEquals(u.Id, [SELECT OwnerId FROM Opportunity WHERE Id = :o.Id].OwnerId,
            'Sanity check: the opportunity really is owned by the other user.');
    }

    /* ------------------------------------------------------------------ */
    /* insert that is not a win                                           */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void insertThatIsNotWonChangesNothing() {
        Account acctA = makeAccount(WARM);
        Account acctB = makeAccount(COLD);
        insert new List<Account>{ acctA, acctB };

        Opportunity prospecting = makeOpportunity('Still prospecting', PROSPECTING, Date.newInstance(2025, 5, 9), acctA.Id);
        prospecting.NextStep = 'Left alone - prospecting';
        Opportunity lost = makeOpportunity('Lost on insert', LOST, Date.newInstance(2025, 5, 10), acctB.Id);
        lost.NextStep = 'Left alone - lost';

        insert new List<Opportunity>{ lost, prospecting };

        System.assertEquals('Left alone - prospecting', nextStepOf(prospecting.Id),
            'NextStep must not be overwritten for an opportunity that is not Closed Won.');
        System.assertEquals('Left alone - lost', nextStepOf(lost.Id),
            'NextStep must not be overwritten for a lost opportunity.');

        Set<Id> ids = new Set<Id>{ prospecting.Id, lost.Id };
        System.assertEquals(0, tasksFor(ids).size(), 'No task may be created for a non-won insert.');

        System.assertEquals(WARM, ratingOf(acctA.Id), 'The account of a non-won opportunity must not be re-rated.');
        System.assertEquals(COLD, ratingOf(acctB.Id), 'The account of a lost opportunity must not be re-rated.');
    }

    /* ------------------------------------------------------------------ */
    /* update to Closed Won                                               */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void updateToClosedWonAppliesFullHandover() {
        Account acct = makeAccount(COLD);
        insert acct;

        Opportunity o = makeOpportunity('Won on update', PROSPECTING, Date.newInstance(2024, 12, 30), acct.Id);
        o.NextStep = 'Not handed over yet';
        insert o;
        System.assertEquals(0, tasksFor(new Set<Id>{ o.Id }).size(),
            'No task exists before the opportunity is won.');

        o.StageName = WON;
        o.NextStep = 'Should be replaced';

        update o;

        System.assertEquals(HANDOVER, nextStepOf(o.Id),
            'NextStep must be set when the stage changes to Closed Won.');

        List<Task> tasks = tasksFor(new Set<Id>{ o.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        Task t = tasks[0];
        System.assertEquals(KICK_OFF, t.Subject, 'The task subject must be "Customer kick-off".');
        System.assertEquals(o.Id, t.WhatId, 'The task must be linked to the opportunity.');
        System.assertEquals(HIGH, t.Priority, 'The task priority must be High.');
        System.assertEquals(Date.newInstance(2025, 1, 6), t.ActivityDate,
            'ActivityDate must be CloseDate + 7 days, including across a year boundary.');

        Opportunity saved = [SELECT OwnerId FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(saved.OwnerId, t.OwnerId, 'The task must be owned by the opportunity owner.');

        System.assertEquals(HOT, ratingOf(acct.Id), 'The account must be re-rated Hot.');
    }

    /* ------------------------------------------------------------------ */
    /* updates that change nothing                                        */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void updateOnAlreadyWonOpportunityChangesNothing() {
        Account acct = makeAccount(WARM);
        insert acct;

        Opportunity o = makeOpportunity('Already won', WON, Date.newInstance(2025, 6, 2), acct.Id);
        insert o;
        System.assertEquals(1, tasksFor(new Set<Id>{ o.Id }).size(),
            'The initial win created exactly one task.');
        System.assertEquals(HANDOVER, nextStepOf(o.Id), 'Sanity check: the handover text was written.');
        System.assertEquals(HOT, ratingOf(acct.Id), 'Sanity check: the account was re-rated.');

        o.NextStep = 'Renegotiated next step';
        o.CloseDate = Date.newInstance(2025, 7, 2);
        update o;

        System.assertEquals('Renegotiated next step', nextStepOf(o.Id),
            'Editing an opportunity that is already won must not overwrite NextStep.');
        System.assertEquals(1, tasksFor(new Set<Id>{ o.Id }).size(),
            'No second kick-off task may be created for an already-won opportunity.');
        System.assertEquals(HOT, ratingOf(acct.Id), 'The account rating must remain Hot.');
    }

    @IsTest
    static void updateFromClosedWonToClosedLostChangesNothing() {
        Account acct = makeAccount(WARM);
        insert acct;

        Opportunity o = makeOpportunity('Losing it', WON, Date.newInstance(2025, 4, 10), acct.Id);
        insert o;
        System.assertEquals(1, tasksFor(new Set<Id>{ o.Id }).size(),
            'The initial win created exactly one task.');
        System.assertEquals(HOT, ratingOf(acct.Id), 'Sanity check: the account was re-rated.');

        o.StageName = LOST;
        o.NextStep = 'Back with sales';
        update o;

        System.assertEquals('Back with sales', nextStepOf(o.Id),
            'An update that leaves Closed Won must not write the handover text.');
        System.assertEquals(1, tasksFor(new Set<Id>{ o.Id }).size(),
