/**
 * Runtime service for reading picklist / multi-select picklist metadata.
 *
 * All failures are reported as PicklistService.PicklistServiceException so
 * callers never have to deal with NullPointerExceptions or describe-related
 * system exceptions.
 */
public with sharing class PicklistService {

    /**
     * Custom exception thrown for invalid input or a failed metadata lookup.
     */
    public class PicklistServiceException extends Exception { }

    /**
     * A single active picklist entry.
     */
    public class Option {
        /** The API (stored) value of the entry, e.g. "In_Progress". */
        public String value;
        /** The display label of the entry, e.g. "In Progress". */
        public String label;
        /** True only when this entry is the field's default value. */
        public Boolean isDefault;

        /** No-argument constructor (safe defaults). */
        public Option() {
            this.value = null;
            this.label = null;
            this.isDefault = false;
        }

        /**
         * @param value     API value of the entry
         * @param label     Display label of the entry
         * @param isDefault Whether the entry is the field's default value
         */
        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Returns the active values of the given picklist (or multi-select picklist)
     * field, in the order they are defined on the field. Inactive values are omitted.
     *
     * @param objectApiName Object API name, case-insensitive (standard or custom)
     * @param fieldApiName  Field API name, case-insensitive (standard or custom)
     * @return List of Option, one per active value, in field definition order
     * @throws PicklistServiceException if either name is null/blank, the object does
     *         not exist, the field does not exist on the object, or the field is not
     *         a picklist / multi-select picklist
     */
    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        // 1. Validate the inputs (null / blank / whitespace only).
        String objectName = requireNonBlank(objectApiName, 'Object API name');
        String fieldName = requireNonBlank(fieldApiName, 'Field API name');

        // 2. Resolve the object, case-insensitively.
        Schema.SObjectType sObjectType = findSObjectType(objectName);
        if (sObjectType == null) {
            throw new PicklistServiceException(
                'SObject "' + objectName + '" does not exist.'
            );
        }
        Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe();

        // 3. Resolve the field on that object, case-insensitively.
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();
        Schema.SObjectField sObjectField = fieldMap.get(fieldName);
        if (sObjectField == null) {
            sObjectField = findSObjectField(fieldMap, fieldName);
        }
        if (sObjectField == null) {
            throw new PicklistServiceException(
                'Field "' + fieldName + '" does not exist on "' + objectDescribe.getName() + '".'
            );
        }

        // 4. The field must be a picklist or a multi-select picklist.
        Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
        Schema.DisplayType displayType = fieldDescribe.getType();
        if (displayType != Schema.DisplayType.PICKLIST
            && displayType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field "' + fieldDescribe.getName() + '" on "' + objectDescribe.getName()
                + '" is not a picklist or multi-select picklist (type: ' + displayType + ').'
            );
        }

        // 5. Build the result: active entries only, preserving definition order.
        List<PicklistService.Option> options = new List<PicklistService.Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry == null) {
                continue;
            }
            if (!entry.isActive()) {
                continue; // inactive values are left out
            }
            Boolean isDefault = (entry.isDefaultValue() == true);
            options.add(new Option(entry.getValue(), entry.getLabel(), isDefault));
        }
        return options;
    }

    /**
     * Trims and validates a required API name.
     *
     * @throws PicklistServiceException when the value is null, blank or whitespace only
     */
    private static String requireNonBlank(String value, String label) {
        if (String.isBlank(value)) {
            throw new PicklistServiceException(label + ' must not be null or blank.');
        }
        return value.trim();
    }

    /**
     * Case-insensitive lookup of an SObject type in the global describe.
     *
     * @return the SObjectType, or null when no object matches the name
     */
    private static Schema.SObjectType findSObjectType(String objectName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        // Fast path: describe maps already resolve keys case-insensitively.
        Schema.SObjectType sObjectType = globalDescribe.get(objectName);
        if (sObjectType != null) {
            return sObjectType;
        }
        // Defensive fallback: explicit case-insensitive match.
        for (String key : globalDescribe.keySet()) {
            if (key != null && key.equalsIgnoreCase(objectName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    /**
     * Case-insensitive lookup of a field in a field describe map.
     *
     * @return the SObjectField, or null when no field matches the name
     */
    private static Schema.SObjectField findSObjectField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName
    ) {
        if (fieldMap == null) {
            return null;
        }
        Schema.SObjectField sObjectField = fieldMap.get(fieldName);
        if (sObjectField != null) {
            return sObjectField;
        }
        for (String key : fieldMap.keySet()) {
            if (key != null && key.equalsIgnoreCase(fieldName)) {
                return fieldMap.get(key);
            }
        }
        return null;
    }
}
