```apex
/**
 * Re-rates Accounts on demand from a button.
 *
 * The job is chunked: every execution handles at most BATCH_SIZE (200) accounts
 * (the first 200 Ids of the list it was constructed with) with exactly one SOQL
 * query and one DML statement, then chains the Ids that are still unprocessed
 * onto a new instance of itself, so a single call to start() can walk through a
 * list of up to 50,000 Ids.
 *
 * The chaining is never suppressed while tests are running: the chain produced
 * inside Test.startTest()/Test.stopTest() is executed by the test runner, which
 * makes the whole chain verifiable from a single test method.
 */
public class AccountScoringJob implements Queueable {

    /** Maximum number of accounts processed by one execution. */
    public static final Integer BATCH_SIZE = 200;

    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    /** Ids that still have to be rated; the first BATCH_SIZE of them are handled here. */
    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(QueueableContext context) {
        // context is intentionally unused so the job can also be invoked directly
        // (execute(null)) from tests.
        List<Id> ids = this.accountIds;
        if (ids == null || ids.isEmpty()) {
            return;
        }

        Integer total = ids.size();
        Integer take = total <= BATCH_SIZE ? total : BATCH_SIZE;

        // One SOQL query for this execution: the first BATCH_SIZE Ids of the list.
        List<Id> batchIds = new List<Id>(ids.subList(0, take));
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account account : accounts) {
            Decimal revenue = account.AnnualRevenue;
            if (revenue != null && revenue >= HOT_THRESHOLD) {
                account.Rating = 'Hot';
            } else if (revenue != null && revenue >= WARM_THRESHOLD) {
                account.Rating = 'Warm';
            } else {
                // Below the thresholds, blank/absent revenue included.
                account.Rating = 'Cold';
            }
        }

        // One DML statement for this execution: all queried accounts in a single update.
        update accounts;

        // Chain whatever is left - also while tests are running - so that the whole
        // list is rated after Test.stopTest().
        if (total > take) {
            System.enqueueJob(new AccountScoringJob(ids.subList(take, total)));
        }
    }

    /**
     * Enqueues the first job of the chain and returns its job Id.
     * A null or empty list enqueues nothing and returns null.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
