/**
 * Delegates every opportunity change to OpportunityPipelineHandler, which keeps
 * FB_Open_Pipeline__c and FB_Open_Opportunities__c on Account in sync.
 *
 * AFTER events only: the roll-ups can only be computed once the DML of the
 * current trigger invocation has been applied.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update, after delete, after undelete) {
    // Trigger.new is null in delete triggers, Trigger.old is null in insert and
    // undelete triggers - pass only what exists in the current context.
    List<Opportunity> newRecords = Trigger.isDelete ? null : Trigger.new;
    List<Opportunity> oldRecords = (Trigger.isInsert || Trigger.isUndelete) ? null : Trigger.old;

    OpportunityPipelineHandler.handle(Trigger.operationType, newRecords, oldRecords);
}
