File: force-app/main/default/classes/OpportunityPipelineHandler.cls
```apex
/**
 * Apex replacement for the two roll-up summary fields Account can no longer
 * declare (the org is at its roll-up limit):
 *
 *     FB_Open_Pipeline__c      = SUM(Opportunity.Amount) WHERE IsClosed = false
 *                                (blank amounts count as 0 - SUM ignores nulls)
 *     FB_Open_Opportunities__c = COUNT(Opportunity)      WHERE IsClosed = false
 *
 * Design notes
 * ------------
 * - Every invocation recalculates the touched accounts from scratch with one
 *   aggregate query instead of applying deltas, and the class keeps no static
 *   state between DML statements. Several DML statements on the same records
 *   inside one transaction (Flow + Apex, several statements in a test method)
 *   therefore always leave correct values - a "handled once per transaction"
 *   guard would not.
 * - Updates are only considered when a roll-up relevant field changed
 *   (Amount, AccountId, StageName/IsClosed). The legacy AccountTrigger only
 *   writes FB_Account_Rating__c, so its bookkeeping update is ignored and the
 *   recursion AccountTrigger -> OpportunityTrigger stops after one level.
 * - Accounts are written back only when the stored value really differs, which
 *   avoids useless DML and a second AccountTrigger run.
 * - Bulk safe: 2 SOQL queries + at most 1 DML per trigger invocation, for 1 or
 *   for 200 opportunities.
 * - without sharing: the totals must include every opportunity of the account
 *   regardless of the running user's sharing rules, so the roll-up can never be
 *   computed from an incomplete record set.
 * - CRUD/FLS enforcement is deliberately not applied here: the two fields are
 *   maintained data, not user input, and restricting them would leave the
 *   roll-ups wrong for users without edit access.
 */
public without sharing class OpportunityPipelineHandler {

    /**
     * Entry point called by OpportunityTrigger.
     *
     * @param operation  Trigger.operationType of the current invocation
     * @param newRecords Trigger.new (null in delete triggers)
     * @param oldRecords Trigger.old (null in insert and undelete triggers)
     */
    public static void handle(
        System.TriggerOperation operation,
        List<Opportunity> newRecords,
        List<Opportunity> oldRecords
    ) {
        if (operation != System.TriggerOperation.AFTER_INSERT
            && operation != System.TriggerOperation.AFTER_UPDATE
            && operation != System.TriggerOperation.AFTER_DELETE
            && operation != System.TriggerOperation.AFTER_UNDELETE) {
            return;
        }

        Set<Id> accountIds = collectAccountIds(operation, newRecords, oldRecords);
        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    /**
     * Returns the set of accounts whose roll-ups may have changed:
     * - insert / delete / undelete: every account referenced by the records
     *   (an account that has just lost its last open opportunity must show 0/0)
     * - update: both the old and the new account, and only if a field that the
     *   roll-ups depend on (Amount, AccountId, StageName/IsClosed) changed.
     */
    private static Set<Id> collectAccountIds(
        System.TriggerOperation operation,
        List<Opportunity> newRecords,
        List<Opportunity> oldRecords
    ) {
        Set<Id> accountIds = new Set<Id>();

        if (operation == System.TriggerOperation.AFTER_UPDATE) {
            for (Integer i = 0; i < newRecords.size(); i++) {
                if (isRollUpRelevant(newRecords[i], oldRecords[i])) {
                    addAccountId(accountIds, oldRecords[i].AccountId);
                    addAccountId(accountIds, newRecords[i].AccountId);
                }
            }
            return accountIds;
        }

        if (newRecords != null) {
            for (Opportunity opp : newRecords) {
                addAccountId(accountIds, opp.AccountId);
            }
        }
        if (oldRecords != null) {
            for (Opportunity opp : oldRecords) {
                addAccountId(accountIds, opp.AccountId);
            }
        }
        return accountIds;
    }

    private static Boolean isRollUpRelevant(Opportunity newRecord, Opportunity oldRecord) {
        return newRecord.Amount != oldRecord.Amount
            || newRecord.AccountId != oldRecord.AccountId
            || newRecord.StageName != oldRecord.StageName
            || newRecord.IsClosed != oldRecord.IsClosed;
    }

    private static void addAccountId(Set<Id> accountIds, Id accountId) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }

    /**
     * Recomputes both fields for every touched account from the database and
     * writes back only the accounts whose stored values actually differ.
     * Accounts without any open opportunity get 0 and 0 (never blank).
     */
    private static void recalculate(Set<Id> accountIds) {
        Map<Id, Decimal> totalsByAccount = new Map<Id, Decimal>();
        Map<Id, Decimal> countsByAccount = new Map<Id, Decimal>();

        // One aggregate query for the whole set - no SOQL in a loop.
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');

            Object rawTotal = ar.get('totalAmount');
            Decimal total = 0;
            if (rawTotal != null) {
                total = (Decimal) rawTotal;
            }

            totalsByAccount.put(accountId, total);
            countsByAccount.put(accountId, toDecimal(ar.get('openCount')));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account accountRecord : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            // Map.get returns null when the account has no open opportunity.
            Decimal newTotal = totalsByAccount.get(accountRecord.Id);
            if (newTotal == null) {
                newTotal = 0;
            }
            Decimal newCount = countsByAccount.get(accountRecord.Id);
            if (newCount == null) {
                newCount = 0;
            }

            Boolean changed = false;
            // A stored null must be replaced as well, so a "0 / 0" account is
            // never left blank.
            if (accountRecord.FB_Open_Pipeline__c == null
                || accountRecord.FB_Open_Pipeline__c != newTotal) {
                accountRecord.FB_Open_Pipeline__c = newTotal;
                changed = true;
            }
            if (accountRecord.FB_Open_Opportunities__c == null
                || accountRecord.FB_Open_Opportunities__c != newCount) {
                accountRecord.FB_Open_Opportunities__c = newCount;
                changed = true;
            }
            if (changed) {
                accountsToUpdate.add(accountRecord);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    /**
     * COUNT aggregates can come back as Integer, Long or Decimal depending on
     * the API version - normalise without relying on a single cast.
     */
    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return 0;
        }
        return Decimal.valueOf(String.valueOf(value));
    }
}
