public class LogPurgeJob implements Schedulable {

    // Standard 30-day retention for non-ERROR logs.
    private static final Integer STANDARD_RETENTION_DAYS = 30;
    // Extended retention for ERROR logs.
    private static final Integer ERROR_RETENTION_DAYS = 180;
    // DML rows are capped at 10,000 per transaction; delete in smaller chunks.
    private static final Integer DELETE_CHUNK_SIZE = 2000;
    // Nightly schedule: every day at 02:00 UTC.
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';
    private static final String NIGHTLY_JOB_NAME = 'Log purge (nightly)';

    // No-argument constructor required by the scheduler.
    public LogPurgeJob() {
    }

    /**
     * Deletes integration logs that are past their retention window:
     *  - ERROR logs are kept for 180 days.
     *  - All other logs (including those with a blank Level__c) are kept for 30 days.
     */
    public void execute(SchedulableContext sc) {
        Datetime standardCutOff = Datetime.now().addDays(-STANDARD_RETENTION_DAYS);
        Datetime errorCutOff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        // Note: SOQL inequality comparisons do not match NULL values, so Level__c = NULL
        // must be tested explicitly to include logs with a blank level.
        List<FB_Integration_Log__c> expiredLogs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE
                (
                    (Level__c = NULL OR Level__c <> 'ERROR')
                    AND CreatedDate < :standardCutOff
                )
                OR
                (
                    Level__c = 'ERROR'
                    AND CreatedDate < :errorCutOff
                )
            ORDER BY CreatedDate ASC
            LIMIT 10000
        ];

        if (expiredLogs.isEmpty()) {
            return;
        }

        // Bulk-safe, partial-success deletion in chunks so a single bad record
        // never aborts the whole purge.
        for (Integer i = 0; i < expiredLogs.size(); i += DELETE_CHUNK_SIZE) {
            Integer endIndex = Math.min(i + DELETE_CHUNK_SIZE, expiredLogs.size());
            List<FB_Integration_Log__c> chunk = new List<FB_Integration_Log__c>();
            for (Integer j = i; j < endIndex; j++) {
                chunk.add(expiredLogs[j]);
            }
            Database.delete(chunk, false /* allOrNone */);
        }
    }

    /**
     * Schedules the purge to run nightly at 02:00 and returns the scheduled job Id.
     */
    public static Id scheduleNightly() {
        return System.schedule(NIGHTLY_JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }
}
