public class CaseEscalationService {

    public class EscalationException extends Exception {
    }

    /**
     * Escalates the given cases: marks them IsEscalated with Priority 'High'
     * and creates a follow-up Task for each. All DML goes through a single
     * unit of work. Blank reason fails fast before any read or write.
     */
    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> casesToEscalate = new List<Case>();
        for (Case record : CasesSelector.newInstance().selectById(caseIds)) {
            if (record == null) {
                continue;
            }
            if (record.Status == 'Closed' || record.IsEscalated) {
                continue;
            }
            casesToEscalate.add(record);
        }

        if (casesToEscalate.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Date tomorrow = Date.today().addDays(1);

        for (Case record : casesToEscalate) {
            record.IsEscalated = true;
            record.Priority = 'High';
            uow.registerDirty(record);

            uow.registerNew(
                new Task(
                    Subject = 'Escalated: ' + reason,
                    WhatId = record.Id,
                    OwnerId = record.OwnerId,
                    ActivityDate = tomorrow,
                    Priority = 'High'
                )
            );
        }

        uow.commitWork();
    }
}
