```apex
/**
 * Service layer responsible for creating onboarding Accounts together with their Contacts.
 *
 * The class follows the Apex Enterprise Patterns (fflib-apex-common) Unit of Work pattern:
 * every record is registered on a single fflib_SObjectUnitOfWork which performs exactly
 * one DML operation per object type when commitWork() is called. No DML statement is
 * written in this class, so the whole operation is atomic, bulk safe and easy to test.
 */
public with sharing class AccountOnboardingService
{
	/**
	 * Creates one Account per map key and, for every last name listed for that key,
	 * one Contact (LastName = value) whose AccountId points at that new Account.
	 *
	 * All records are written through a single unit of work committed once; if the map
	 * is null or empty nothing is written at all.
	 *
	 * @param contactLastNamesByAccountName Map of Account name -> list of Contact last names
	 * @return The newly created Accounts with their Ids populated (empty list when there
	 *         is nothing to create)
	 */
	public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName)
	{
		List<Account> newAccounts = new List<Account>();

		// Nothing to do: return early without creating a unit of work (writes nothing).
		if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty())
		{
			return newAccounts;
		}

		// Parent object types must be registered before their children so that the
		// Account Ids are already available when the Contacts are inserted.
		fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
			new List<Schema.SObjectType>
			{
				Account.SObjectType,
				Contact.SObjectType
			}
		);

		for (String accountName : contactLastNamesByAccountName.keySet())
		{
			if (String.isBlank(accountName))
			{
				// Account.Name is required, a blank name can never be saved.
				continue;
			}

			Account account = new Account(Name = accountName);
			uow.registerNew(account);
			newAccounts.add(account);

			List<String> lastNames = contactLastNamesByAccountName.get(accountName);
			if (lastNames == null || lastNames.isEmpty())
			{
				// An Account without contacts is still created.
				continue;
			}

			for (String lastName : lastNames)
			{
				if (String.isBlank(lastName))
				{
					// Contact.LastName is required, a blank value can never be saved.
					continue;
				}

				Contact contact = new Contact(LastName = lastName);
				uow.registerNew(contact);
				// Relate the contact to the (still uninserted) account; the unit of work
				// resolves AccountId as soon as the Account has been inserted.
				uow.registerRelationship(contact, Contact.AccountId, account);
			}
		}

		// Nothing was registered - do not write anything.
		if (newAccounts.isEmpty())
		{
			return newAccounts;
		}

		// Single bulk-safe DML execution for every Account and Contact, exactly once.
		uow.commitWork();

		// commitWork() populated the Ids on the registered records.
		return newAccounts;
	}
}
