```apex
/**
 * Keeps Account.Rating in step with the account's open pipeline.
 *
 * Every relevant change is handed to AccountRatingService.recalculate(Id), which is an
 * @future method, so the opportunity save itself stays fast (our CPQ integration inserts
 * and updates opportunities in batches of 200).
 *
 * Events handled:
 *   after insert    - new opportunity on an account
 *   after update    - StageName, Amount or AccountId changed
 *   after delete    - the last open opportunity disappearing must put the account back to Cold
 *   after undelete  - and an undeleted open opportunity must raise it again
 */
trigger OpportunityTrigger on Opportunity (after insert, after update, after delete, after undelete) {

    if (Trigger.isUpdate) {

        for (Opportunity opp : Trigger.new) {

            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);

            // Recalculate only when something that can move the rating actually moved.
            boolean ratingRelevant = opp.StageName != oldOpp.StageName
                || opp.Amount != oldOpp.Amount
                || opp.AccountId != oldOpp.AccountId;

            if (!ratingRelevant) {
                continue;
            }

            // If the opportunity was moved to another account, the account it left
            // no longer has this pipeline and would otherwise keep a stale rating.
            if (opp.AccountId != oldOpp.AccountId && oldOpp.AccountId != null) {
                AccountRatingService.recalculate(oldOpp.AccountId);
            }

            if (opp.AccountId != null) {
                AccountRatingService.recalculate(opp.AccountId);
            }
        }

    } else {

        // after insert / after undelete -> Trigger.new
        // after delete                  -> Trigger.old
        List<Opportunity> opportunities = Trigger.isDelete ? Trigger.old : Trigger.new;

        for (Opportunity opp : opportunities) {
            if (opp.AccountId != null) {
                AccountRatingService.recalculate(opp.AccountId);
            }
        }
    }
}
```

