trigger CaseTrigger on Case (after update) {

    // ---------------------------------------------------------------------
    // 1. Work out which cases were just closed (not closed -> closed) and
    //    that have a contact to send the survey to. Pure in-memory work on
    //    the trigger context - no SOQL, no DML, nothing in a loop.
    // ---------------------------------------------------------------------
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case updatedCase : Trigger.new) {
        Case previousCase = Trigger.oldMap.get(updatedCase.Id);
        if (previousCase == null) {
            continue;
        }

        if (updatedCase.IsClosed
                && !previousCase.IsClosed
                && updatedCase.ContactId != null) {
            newlyClosedCaseIds.add(updatedCase.Id);
        }
        // Cases without a contact are intentionally never enqueued.
    }

    if (newlyClosedCaseIds.isEmpty()) {
        return;
    }

    // ---------------------------------------------------------------------
    // 2. One queueable job per case, so each case is isolated: an exception
    //    while creating the survey task for one case never affects the
    //    others, and the (growing) survey logic stays out of this transaction.
    // ---------------------------------------------------------------------
    Integer index = 0;
    while (index < newlyClosedCaseIds.size()) {

        // Keep one free slot. Salesforce only allows 50 enqueueJob calls per
        // transaction, but list-view / Bulk API closes can hand us 200 cases.
        // Rather than blowing the governor limit (an uncatchable
        // LimitException would roll the whole close back), the tail is handed
        // to a single chained CaseSurveyJob that splits it again from a fresh
        // transaction.
        if (Limits.getQueueableJobs() >= Limits.getLimitQueueableJobs() - 1) {
            List<Id> remainingCaseIds = new List<Id>();
            for (Integer i = index; i < newlyClosedCaseIds.size(); i++) {
                remainingCaseIds.add(newlyClosedCaseIds[i]);
            }
            System.enqueueJob(new CaseSurveyJob(remainingCaseIds));
            return;
        }

        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds[index]));
        index++;
    }
}
