import { LightningElement, api, wire } from 'lwc';
import { getRecord, FIELD_NAME_FIELD, FIELD_INDUSTRY_FIELD, FIELD_ANNUAL_REVENUE_FIELD, FIELD_OWNER_NAME_FIELD } from 'lightning/uiRecordApi';

// Requested fields for the Account record
const FIELDS = [FIELD_NAME_FIELD];
const OPTIONAL_FIELDS = [
    FIELD_INDUSTRY_FIELD,
    FIELD_ANNUAL_REVENUE_FIELD,
    FIELD_OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    /**
     * The record Id provided by the record page.
     * It is a public property so the wire adapter is re-evaluated
     * automatically whenever the value changes (e.g. a reused console tab).
     */
    @api recordId;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: FIELDS,
        optionalFields: OPTIONAL_FIELDS
    })
    account;

    /**
     * True while the record has neither loaded nor errored.
     */
    get isLoading() {
        return !this.account || (!this.account.data && !this.account.error);
    }

    get hasData() {
        return !!(this.account && this.account.data);
    }

    get hasError() {
        return !!(this.account && this.account.error);
    }

    get name() {
        return this.hasData ? this.account.data.fields.Name.value : null;
    }

    get industry() {
        return this.hasData ? this.account.data.fields.Industry.value : null;
    }

    get showIndustry() {
        const value = this.industry;
        return value !== undefined && value !== null && value !== '';
    }

    get annualRevenue() {
        return this.hasData ? this.account.data.fields.AnnualRevenue.value : null;
    }

    get ownerName() {
        if (!this.hasData) {
            return null;
        }
        const ownerField = this.account.data.fields.Owner;
        if (!ownerField || !ownerField.value) {
            return null;
        }
        // Owner is a lookup; its display value is the owner's name.
        const displayValue = ownerField.displayValue;
        if (displayValue) {
            return displayValue;
        }
        return ownerField.value.fields && ownerField.value.fields.Name
            ? ownerField.value.fields.Name.value
            : null;
    }

    get errorMessage() {
        return this.hasError ? this.account.error.body.message : null;
    }
}
