/**
 * Reusable WAI-ARIA disclosure section.
 *
 * Usage:
 *   <c-collapsible-section>
 *       <span slot="title">Billing details</span>
 *       <p>Any body content…</p>
 *   </c-collapsible-section>
 *
 * - The section starts collapsed.
 * - The toggle button exposes aria-expanded and aria-controls.
 * - The body div is always present in the DOM (so aria-controls always
 *   resolves); it is hidden via the `hidden` attribute while collapsed.
 */
import { LightningElement } from 'lwc';

/**
 * Module-level counter so every instance of this component on the same page
 * gets a unique, stable id for its section body (aria-controls target).
 */
let instanceCounter = 0;

export default class CollapsibleSection extends LightningElement {
    /**
     * Whether the section body is currently visible.
     * @type {boolean}
     */
    isExpanded = false;

    /**
     * Unique id for the section body element. Generated once, on
     * instantiation, so aria-controls always points at the same element.
     * @type {string}
     */
    bodyId = `collapsible-section-body-${instanceCounter++}`;

    /**
     * aria-expanded must be the literal string "true" or "false".
     * @returns {string}
     */
    get ariaExpanded() {
        return this.isExpanded ? 'true' : 'false';
    }

    /**
     * @returns {boolean} true when the section body should be hidden.
     */
    get isCollapsed() {
        return !this.isExpanded;
    }

    /**
     * Toggles the disclosure. The native <button> already gives us
     * Enter/Space keyboard activation, so no extra key handling is needed.
     */
    handleToggle() {
        this.isExpanded = !this.isExpanded;
    }
}
