import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    /**
     * The parent owns this array. Each element is an object with
     * { Id, Name, Title } where Title may be missing.
     */
    _contacts = [];

    @api
    get contacts() {
        return this._contacts;
    }

    set contacts(value) {
        // Defensive: the parent may pass undefined, null, or a non-array value.
        this._contacts = Array.isArray(value) ? value : [];
    }

    /**
     * Sorted copy (ascending by Name) — never mutates the parent's array.
     */
    get sortedContacts() {
        return [...this._contacts]
            .filter((contact) => contact && contact.Name)
            .sort((a, b) => String(a.Name).localeCompare(String(b.Name)));
    }

    get isEmpty() {
        return this._contacts.length === 0;
    }

    get countLabel() {
        const total = this._contacts.length;
        return total === 1 ? '1 contact' : `${total} contacts`;
    }
}
