import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_QUERY_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    // Bound to <lightning-input> so the field always reflects the typed text.
    searchTerm = '';
    results = [];
    error;

    // Debounce timer handle.
    _debounceTimer = null;
    // Monotonic counter used to discard out-of-order / stale responses.
    _requestSequence = 0;

    /**
     * Fires on every keystroke for lightning-input type="search".
     */
    handleChange(event) {
        this.searchTerm = event.target.value;
        this._scheduleSearch();
    }

    /**
     * Restarts the 300 ms debounce window with the latest trimmed value.
     * Any previously pending search is cancelled first, so only one timer
     * can ever be outstanding.
     */
    _scheduleSearch() {
        this._clearDebounce();

        const term = (this.searchTerm || '').trim();

        // Not enough to search on: cancel pending work, don't call Apex,
        // and clear any previously rendered results.
        if (term.length < MIN_QUERY_LENGTH) {
            this.results = [];
            this.error = undefined;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;
            this._runSearch();
        }, DEBOUNCE_DELAY_MS);
    }

    /**
     * Executes the imperative Apex call with the latest trimmed value.
     */
    _runSearch() {
        // The component may have been removed while the debounce was pending.
        if (!this.isConnected) {
            return;
        }

        const term = (this.searchTerm || '').trim();
        if (term.length < MIN_QUERY_LENGTH) {
            this.results = [];
            this.error = undefined;
            return;
        }

        const requestId = ++this._requestSequence;

        searchContacts({ searchTerm: term })
            .then((contacts) => {
                // Only the most recent request may update the results.
                if (requestId !== this._requestSequence) {
                    return;
                }
                this.results = Array.isArray(contacts) ? contacts : [];
                this.error = undefined;
            })
            .catch((err) => {
                // Same guard for failures: ignore stale errors.
                if (requestId !== this._requestSequence) {
                    return;
                }
                this.results = [];
                this.error = err;
            });
    }

    /**
     * Lifecycle cleanup: no search may start once the component is gone,
     * and any in-flight response is invalidated.
     */
    disconnectedCallback() {
        this._clearDebounce();
        // Invalidate responses still in flight for a removed instance.
        this._requestSequence += 1;
    }

    _clearDebounce() {
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
    }

    get hasResults() {
        return Array.isArray(this.results) && this.results.length > 0;
    }

    get errorMessage() {
        if (!this.error) {
            return '';
        }
        if (this.error.body && this.error.body.message) {
            return this.error.body.message;
        }
        return String(this.error.message || this.error);
    }
}
