import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    /** The Account record Id (set by the record page). */
    @api recordId;

    /** Opportunities returned by Apex. */
    opportunities = [];

    /** True while an Apex call is in flight. */
    isLoading = false;

    /** Error object from the last failed Apex call. */
    error;

    /**
     * Load the account's open opportunities exactly once when the
     * component is inserted into the page.
     */
    connectedCallback() {
        this.loadOpportunities();
    }

    /** Imperatively call Apex; shows the spinner while the call runs. */
    async loadOpportunities() {
        this.isLoading = true;
        this.error = undefined;
        try {
            const results = await getOpenOpportunities({ accountId: this.recordId });
            this.opportunities = Array.isArray(results) ? results : [];
        } catch (error) {
            this.opportunities = [];
            this.error = error;
        } finally {
            this.isLoading = false;
        }
    }

    /** Retry a failed call; the spinner is shown again while it runs. */
    handleRetry() {
        this.loadOpportunities();
    }

    /** Render the list only when there is at least one opportunity. */
    get hasOpportunities() {
        return Array.isArray(this.opportunities) && this.opportunities.length > 0;
    }
}
