    { label: 'Stage', fieldName: 'StageName' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    columns = COLUMNS;

    _opportunities = [];

    /**
     * Public property passed in by the parent.
     * We copy the incoming array into a private backing field so that removing a
     * deleted row never mutates the parent's array.
     */
    @api
    get opportunities() {
        return this._opportunities;
    }

    set opportunities(value) {
        this._opportunities = Array.isArray(value) ? [...value] : [];
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this.navigateToRecord(row, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row, 'edit');
                break;
            case 'delete':
                this.confirmAndDelete(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(row, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId: row.Id,
                objectApiName: 'Opportunity',
                actionName: actionName
            }
        });
    }

    async confirmAndDelete(row) {
        let confirmed = false;

        try {
            confirmed = await LightningConfirm.open({
                label: 'Delete Opportunity',
                message: `Are you sure you want to delete ${row.Name}?`,
                theme: 'destructive'
            });
        } catch (error) {
            // Dialog could not be opened / was dismissed without a value: do nothing.
            confirmed = false;
        }

        if (!confirmed) {
            // User cancelled - do nothing.
            return;
        }

        try {
            await deleteRecord(row.Id);

            // Remove the row from a new array (no mutation of the parent's array).
            this._opportunities = this._opportunities.filter(
                (opportunity) => opportunity.Id !== row.Id
            );

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    variant: 'success',
                    message: 'The opportunity has been deleted.'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    variant: 'error',
                    message: error && error.body ? error.body.message : 'An unexpected error occurred.'
                })
            );
        }
    }
}
