import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
const WORK_EMAIL_MESSAGE = 'Use your work email address.';
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    // Keeps the current value of each field from its change event (event.detail.value).
    handleFieldChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail.value;

        switch (field) {
            case 'fullName':
                this.fullName = value;
                break;
            case 'email':
                this.email = value;
                break;
            case 'company':
                this.company = value;
                break;
            default:
                break;
        }
    }

    // Delegated action handler keyed on data-action="register".
    handleAction(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'register') {
            this.handleRegister();
        }
    }

    handleRegister() {
        const fullName = this.getFieldValue('fullName', this.fullName);
        const email = this.getFieldValue('email', this.email);
        const company = this.getFieldValue('company', this.company);

        // (1) Only work email addresses are accepted.
        // This runs before validity is reported so the custom message is included
        // in the report; an empty/corrupt address is left to the built-in rules.
        const emailInput = this.template.querySelector('[data-field="email"]');
        if (emailInput && typeof emailInput.setCustomValidity === 'function') {
            emailInput.setCustomValidity(isWorkEmail(email) ? '' : WORK_EMAIL_MESSAGE);
        }

        // (2) Report every input, never short-circuiting, so all messages show at once.
        const allValid = this.reportInputs();

        // (3) Stop as soon as one input is invalid.
        if (!allValid) {
            return;
        }

        // (4) Register imperatively and toast the outcome.
        register({ fullName, email, company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        variant: 'error',
                        message: getErrorMessage(error)
                    })
                );
            });
    }

    // The value kept from the change event, with the live input value as a safety net.
    getFieldValue(fieldName, fallback) {
        const input = this.template.querySelector(`[data-field="${fieldName}"]`);
        const domValue = input ? input.value : undefined;
        if (domValue !== undefined && domValue !== null && String(domValue).length > 0) {
            return String(domValue);
        }
        return fallback;
    }

    reportInputs() {
        const inputs = Array.from(this.template.querySelectorAll('lightning-input'));
        let allValid = true;

        inputs.forEach((input) => {
            // Always report first: every invalid field displays its message,
            // even when an earlier field is already invalid.
            const reported = typeof input.reportValidity === 'function' ? input.reportValidity() : undefined;
            const checked = typeof input.checkValidity === 'function' ? input.checkValidity() : undefined;
            const validity = input.validity;

            if (reported === false || checked === false || (validity && validity.valid === false)) {
                allValid = false;
                return;
            }

            // The component gave a definitive answer: the value is valid.
            if (reported !== undefined || checked !== undefined || (validity && typeof validity.valid === 'boolean')) {
                return;
            }

            // No validation API exposed on this element - fall back to our own rules.
            if (!this.isFieldValid(input)) {
                allValid = false;
            }
        });

        return allValid;
    }

    isFieldValid(input) {
        const fieldName = input.dataset ? input.dataset.field : '';
        const value = String(this.getFieldValue(fieldName, this[fieldName]) || '').trim();

        if (fieldName === 'fullName') {
            return value.length > 0;
        }
        if (fieldName === 'email') {
            return value.length > 0 && EMAIL_PATTERN.test(value) && isWorkEmail(value);
        }
        // company is optional
        return true;
    }
}

function isWorkEmail(email) {
    const value = String(email || '').trim();
    const atIndex = value.lastIndexOf('@');

    // No domain to inspect - the built-in email/required validation reports it.
    if (atIndex === -1 || atIndex === value.length - 1) {
        return true;
    }

    const domain = value.substring(atIndex + 1).trim().toLowerCase();
    return PERSONAL_EMAIL_DOMAINS.indexOf(domain) === -1;
}

function getErrorMessage(error) {
    if (error && error.body && error.body.message) {
        return error.body.message;
    }
    if (error && error.message) {
        return error.message;
    }
    return 'An unexpected error occurred.';
}
