import { LightningElement, api } from 'lwc';

/**
 * Keys the listbox owns. For these six keys we always call preventDefault();
 * every other key (notably Tab) keeps its native behaviour.
 */
const HANDLED_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' ']);

export default class StatusListbox extends LightningElement {
    /** Accessible name of the list (rendered as aria-label). */
    @api label;

    /** Array of { value, label }. */
    @api options;

    /** Selected value. Can be changed by the parent at any time. */
    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue;
        // The parent moved the selection: move the active option with it.
        this._activeIndex = this.indexOfValue(newValue);
    }

    /** Current selection (may be undefined/empty when nothing is selected). */
    _value;

    /** Index of the active option (-1 when there are no options). */
    _activeIndex = -1;

    /** Unique prefix so option ids are unique across instances in the document. */
    _uid = `sl-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

    /* ------------------------------------------------------------------ */
    /* Rendering                                                           */
    /* ------------------------------------------------------------------ */

    get optionList() {
        return Array.isArray(this.options) ? this.options : [];
    }

    get items() {
        return this.optionList.map((option, index) => ({
            key: this.optionId(index),
            id: this.optionId(index),
            index,
            value: option.value,
            label: option.label,
            selected: option.value === this._value ? 'true' : 'false'
        }));
    }

    /**
     * Clamped active index: never out of bounds, -1 only when there are no options.
     */
    get activeIndex() {
        const count = this.optionList.length;
        if (count === 0) {
            return -1;
        }
        if (this._activeIndex < 0 || this._activeIndex >= count) {
            return 0;
        }
        return this._activeIndex;
    }

    get activeId() {
        const index = this.activeIndex;
        return index < 0 ? undefined : this.optionId(index);
    }

    renderedCallback() {
        this.normalizeActiveIndex();
    }

    /* ------------------------------------------------------------------ */
    /* Keyboard                                                            */
    /* ------------------------------------------------------------------ */

    handleKeydown(event) {
        const key = event.key;

        // Anything else (Tab, Escape, printable characters, ...) keeps its default.
        if (!HANDLED_KEYS.has(key)) {
            return;
        }

        event.preventDefault();

        const count = this.optionList.length;
        if (count === 0) {
            return;
        }

        const current = this.activeIndex;
        let next = current;

        switch (key) {
            case 'ArrowDown':
                // Stop at the last option - no wrap-around.
                next = Math.min(current + 1, count - 1);
                break;
            case 'ArrowUp':
                // Stop at the first option - no wrap-around.
                next = Math.max(current - 1, 0);
                break;
            case 'Home':
                next = 0;
                break;
            case 'End':
                next = count - 1;
                break;
            case 'Enter':
            case ' ':
                // Selecting never moves focus; it only changes the selection.
                this.selectOption(current);
                return;
            default:
                return;
        }

        // Moving the active option does not change the selection.
        this._activeIndex = next;
    }

    /* ------------------------------------------------------------------ */
    /* Pointer                                                             */
    /* ------------------------------------------------------------------ */

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        if (Number.isNaN(index)) {
            return;
        }
        // Focus stays on the list so subsequent arrow keys keep working.
        const list = this.template.querySelector('[role="listbox"]');
        if (list && typeof list.focus === 'function') {
            list.focus();
        }
        this._activeIndex = index;
        this.selectOption(index);
    }

    /* ------------------------------------------------------------------ */
    /* Helpers                                                             */
    /* ------------------------------------------------------------------ */

    selectOption(index) {
        const options = this.optionList;
        if (index < 0 || index >= options.length) {
            return;
        }

        const optionValue = options[index].value;
        const alreadySelected = optionValue === this._value;

        this._value = optionValue;
        this._activeIndex = index;

        if (alreadySelected) {
            return;
        }

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: optionValue },
                bubbles: true,
                composed: true
            })
        );
    }

    indexOfValue(searchValue) {
        if (searchValue === undefined || searchValue === null || searchValue === '') {
            return -1;
        }
        return this.optionList.findIndex((option) => option.value === searchValue);
    }

    optionId(index) {
        return `${this._uid}-option-${index}`;
    }

    /**
     * Keeps the active index valid when the options/value arrive or change
     * out of order: fall back to the selected option, otherwise the first one.
     */
    normalizeActiveIndex() {
        const count = this.optionList.length;
        if (count === 0) {
            this._activeIndex = -1;
            return;
        }
        if (this._activeIndex < 0 || this._activeIndex >= count) {
            const selectedIndex = this.indexOfValue(this._value);
            this._activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
        }
    }
}
