import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    // Public API: never written to, so the parent's value is preserved
    // and later changes from the parent are picked up reactively.
    @api heading;

    // Private copy of the parent's list (the parent's array/objects are never touched).
    _tasks = [];
    // Working copy rendered by the component.
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        const source = Array.isArray(value) ? value : [];
        this._tasks = source.map((task) => ({ ...task }));
        this.items = this._tasks.map((task) => ({ ...task }));
    }

    // Display-only projection of the public heading: upper case, never stored back.
    get displayHeading() {
        if (this.heading === undefined || this.heading === null) {
            return '';
        }
        return String(this.heading).toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel =
            event.detail && event.detail.value !== undefined ? event.detail.value : '';
    }

    handleAdd() {
        const label = typeof this.newLabel === 'string' ? this.newLabel.trim() : '';
        if (!label) {
            return;
        }

        // Unique id, guaranteed not to clash with ids already in the list.
        let id;
        do {
            id = `new-${Date.now()}-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));

        // Reassign (never push) so LWC re-renders the list and the counter.
        this.items = [...this.items, { id, label, done: false }];

        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = String(event.target.dataset.id);
        const index = this.items.findIndex((task) => String(task.id) === id);
        if (index === -1) {
            return;
        }
        // Immutable update so the checkbox and the "remaining" counter refresh.
        this.items = this.items.map((task, i) =>
            i === index ? { ...task, done: !task.done } : task
        );
    }
}
