/**
 * Turns an open donation (pledge) into a monthly installment plan.
 *
 * NPSP gives every new open opportunity one unpaid payment for the full amount.
 * This service replaces the opportunity's "replaceable" payments (unpaid and not
 * written off) with a schedule of `numberOfPayments` unpaid payments, dated
 * monthly from `firstPaymentDate`.
 *
 * Money already settled (paid or written-off payments) is history: those rows are
 * never touched, and their amounts are subtracted from the opportunity Amount so
 * that the new schedule only covers what is still outstanding.
 *
 * All validation happens before any DML, so a failure leaves the org untouched.
 */
public with sharing class PaymentPlanService {

    /** Raised whenever the request cannot be fulfilled. */
    public class PaymentPlanException extends Exception {}

    /**
     * Reschedules the outstanding balance of an opportunity as monthly installments.
     *
     * @param opportunityId     the opportunity (pledge) to reschedule
     * @param numberOfPayments  how many installments to create (>= 1, not null)
     * @param firstPaymentDate  date of installment 0; installment i is addMonths(i)
     * @return the inserted payments, in schedule order (installment 0 first)
     * @throws PaymentPlanException if numberOfPayments is null or < 1, the
     *         opportunity is closed, or the outstanding amount is not > 0
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // ---------------------------------------------------------------------
        // 1. Validation - nothing is changed in the org until every check passes
        // ---------------------------------------------------------------------
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be provided and be greater than or equal to 1.'
            );
        }

        Opportunity opp;
        try {
            opp = [
                SELECT Id, Amount, IsClosed,
                    (
                        SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
                        FROM npe01__OppPayment__r
                    )
                FROM Opportunity
                WHERE Id = :opportunityId
                LIMIT 1
            ];
        } catch (QueryException qe) {
            throw new PaymentPlanException('No opportunity found with Id ' + opportunityId + '.');
        }

        if (opp.IsClosed) {
            throw new PaymentPlanException(
                'Opportunity ' + opp.Id + ' is closed; an installment plan can only be created on an open opportunity.'
            );
        }

        // Outstanding = opportunity Amount - amounts of paid and written-off payments.
        // A payment that is both paid and written off is history and must only be
        // subtracted once, so the two flags are combined with OR.
        Decimal settledAmount = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : opp.npe01__OppPayment__r) {
            Boolean isHistory =
                (payment.npe01__Paid__c == true) || (payment.npe01__Written_Off__c == true);

            if (isHistory) {
                Decimal settled = payment.npe01__Payment_Amount__c;
                if (settled == null) {
                    settled = 0;
                }
                settledAmount += settled;
            } else {
                // Unpaid and not written off: safe to replace with the new schedule.
                paymentsToDelete.add(payment);
            }
        }

        Decimal opportunityAmount = opp.Amount;
        if (opportunityAmount == null) {
            opportunityAmount = 0;
        }
        Decimal outstanding = opportunityAmount - settledAmount;

        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero; found ' + outstanding + '.'
            );
        }

        // ---------------------------------------------------------------------
        // 2. Build the schedule (floor division; last payment absorbs remainder)
        // ---------------------------------------------------------------------
        Decimal baseAmount = outstanding.divide(numberOfPayments, 2, RoundingMode.DOWN);

        List<npe01__OppPayment__c> installments = new List<npe01__OppPayment__c>();
        Decimal allocatedSoFar = 0;

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount;
            if (i == numberOfPayments - 1) {
                // Last installment takes the remainder so the sum is exact.
                amount = outstanding - allocatedSoFar;
            } else {
                amount = baseAmount;
            }
            allocatedSoFar += amount;

            Date scheduledDate;
            if (firstPaymentDate != null) {
                scheduledDate = firstPaymentDate.addMonths(i);
            }

            installments.add(
                new npe01__OppPayment__c(
                    npe01__Opportunity__c = opp.Id,
                    npe01__Payment_Amount__c = amount,
                    npe01__Scheduled_Date__c = scheduledDate,
                    npe01__Payment_Date__c = null,
                    npe01__Paid__c = false,
                    npe01__Written_Off__c = false
                )
            );
        }

        // ---------------------------------------------------------------------
        // 3. DML - only reached when every validation has passed
        // ---------------------------------------------------------------------
        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }
        insert installments;

        // Returned in schedule order: installment 0, 1, ... n-1.
        return installments;
    }
}
