public with sharing class DiscountApprovalService {

    private static final Decimal MAX_SELF_APPROVE_DISCOUNT = 15;

    /**
     * Decides whether the running user may approve the given discount.
     *
     * @param discountPercent The discount as a percentage (e.g. 12.5 for 12.5%).
     * @return false when discountPercent is null or negative;
     *         true when discountPercent is between 0 and 15 inclusive;
     *         for discounts above 15, true only if the running user holds the
     *         Approve_Large_Discount custom permission (checked via FeatureManagement,
     *         which honors the permission regardless of how it was granted -
     *         permission sets, permission set groups, etc.).
     */
    @AuraEnabled
    public static Boolean canApprove(Decimal discountPercent) {
        if (discountPercent == null || discountPercent < 0) {
            return false;
        }
        if (discountPercent <= MAX_SELF_APPROVE_DISCOUNT) {
            return true;
        }
        return FeatureManagement.checkPermission('Approve_Large_Discount');
    }
}
