{
  "orgName": "Globex Integration",
  "edition": "Developer",
  "sampleData": true,
  "features": [
    "ContactsToMultipleAccounts"
  ],
  "settings": {
    "stateAndCountryPicklists": {
      "enableStateAndCountryPicklists": true
    }
  }
}
