/**
 * Service used by the legacy-system contact migration.
 *
 * Bypasses only the TAF action `TA_Contact_CreateWelcomeTask` (after insert) so that
 * migrated contacts do not get a "Send welcome pack" Task, while every other piece of
 * Contact automation - including the `TA_Contact_FormatPhone` before-insert action -
 * still executes normally.
 *
 * The bypass is always torn down in a `finally` block, so it can never leak past this
 * method: contacts inserted later in the same transaction are handled as usual.
 */
public with sharing class ContactImportService {

    /**
     * Fully qualified name of the TAF action registered for Contact in
     * Trigger_Action__mdt (no namespace, unlocked package).
     */
    private static final String SKIP_WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    /**
     * Inserts the supplied contacts in a single DML statement with the welcome-task
     * action bypassed. Bulk-safe: one `insert` for the whole list.
     *
     * @param contacts the contacts to insert; may be null or empty (no-op).
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Bypass the single action (not the object, and not any other action).
        MetadataTriggerHandler.bypass(SKIP_WELCOME_TASK_ACTION);
        try {
            insert contacts;
        } finally {
            // Always release the bypass, even if the DML fails, so that any automation
            // running later in this transaction sees the bypass as inactive.
            MetadataTriggerHandler.clearBypass(SKIP_WELCOME_TASK_ACTION);
        }
    }
}
