/**
 * DML-less / SOQL-less unit tests for TA_Opportunity_GuardAmountDecrease.
 *
 * Follows the Trigger Actions Framework recommendation of exercising the action's
 * context method directly with in-memory trigger.new / trigger.old lists:
 *   - no INSERT / UPDATE / DELETE / UNDELETE and no SELECT statements anywhere,
 *   - record Ids come from TriggerTestUtility.getFakeId(...),
 *   - results are verified with the SObject error API (hasErrors() / getErrors()).
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    private static final String EXPECTED_MESSAGE = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;

    /**
     * Builds a brand new (in-memory) record of the "after" side of the update.
     */
    private static Opportunity newSide(Id recordId, Decimal amount) {
        return new Opportunity(Id = recordId, Amount = amount);
    }

    /**
     * Builds a brand new (in-memory) record of the "before" side of the update.
     */
    private static Opportunity oldSide(Id recordId, Decimal amount) {
        return new Opportunity(Id = recordId, Amount = amount);
    }

    /**
     * Asserts that the record carries exactly one error whose message is ERROR_MESSAGE.
     */
    private static void assertRejected(SObject record, String description) {
        Assert.isTrue(record.hasErrors(), description + ' - expected the record to carry an error.');
        List<Database.Error> errors = record.getErrors();
        Assert.areEqual(1, errors.size(), description + ' - expected exactly one error on the record.');
        Assert.areEqual(EXPECTED_MESSAGE, errors[0].getMessage(), description + ' - unexpected error message.');
    }

    /**
     * Asserts that the record carries no errors at all.
     */
    private static void assertAccepted(SObject record, String description) {
        Assert.isFalse(record.hasErrors(), description + ' - expected the record to carry no errors.');
        Assert.areEqual(0, record.getErrors().size(), description + ' - expected an empty error list.');
    }

    /**
     * 1) A reduction of more than half (1000 -> 499) is rejected with exactly one
     *    error carrying the action's ERROR_MESSAGE constant.
     */
    @IsTest
    static void reductionOfMoreThanHalfIsRejected() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity updated = newSide(recordId, 499);
        Opportunity previousVersion = oldSide(recordId, 1000);
        List<Opportunity> triggerNew = new List<Opportunity>{ updated };
        List<Opportunity> triggerOld = new List<Opportunity>{ previousVersion };

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        assertRejected(updated, '1000 -> 499 must be rejected');
        // The "old" record must never be touched by a before-update action.
        assertAccepted(previousVersion, 'the trigger.old record must not be mutated');
        // The action must not have altered the new values either.
        Assert.areEqual(499, updated.Amount, 'the offending field value must not be changed.');
        Assert.areEqual(1000, previousVersion.Amount, 'the old field value must not be changed.');
    }

    /**
     * 2) A reduction of exactly half (1000 -> 500) is accepted: the comparison is strict (<),
     *    so no error may be raised.
     */
    @IsTest
    static void reductionOfExactlyHalfIsAccepted() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity updated = newSide(recordId, 500);
        Opportunity previousVersion = oldSide(recordId, 1000);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ updated },
            new List<Opportunity>{ previousVersion }
        );

        assertAccepted(updated, '1000 -> 500 must be accepted');
        Assert.areEqual(500, updated.Amount, 'the accepted value must remain 500.');
    }

    /**
     * 3) An increase (1000 -> 2500) is accepted.
     */
    @IsTest
    static void increaseIsAccepted() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity updated = newSide(recordId, 2500);
        Opportunity previousVersion = oldSide(recordId, 1000);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ updated },
            new List<Opportunity>{ previousVersion }
        );

        assertAccepted(updated, '1000 -> 2500 must be accepted');
    }

    /**
     * 4) A record whose previous Amount was null is accepted and must not throw
     *    a NullPointerException (oldMap.get(...).Amount may be null).
     */
    @IsTest
    static void nullPreviousAmountIsAcceptedWithoutException() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity updated = newSide(recordId, 1000);
        Opportunity previousVersion = oldSide(recordId, null);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ updated },
            new List<Opportunity>{ previousVersion }
        );

        assertAccepted(updated, 'a null previous Amount must be accepted');

        // Null on both sides must also be accepted without an exception.
        Id bothNullId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity bothNullNew = newSide(bothNullId, null);
        Opportunity bothNullOld = oldSide(bothNullId, null);

