    }

    /**
     * 5) One call with several records: only the records that break the rule get the error,
     *    the others get none (and only one error per offending record).
     */
    @IsTest
    static void onlyTheViolatingRecordsGetTheError() {
        Id badId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id exactHalfId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id increaseId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id nullOldId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity badNew = newSide(badId, 400);            // 1000 -> 400 : more than half
        Opportunity exactHalfNew = newSide(exactHalfId, 500); // 1000 -> 500 : exactly half
        Opportunity increaseNew = newSide(increaseId, 5000);  // 1000 -> 5000: increase
        Opportunity nullOldNew = newSide(nullOldId, 10);      // null  -> 10  : previous was null

        Opportunity badOld = oldSide(badId, 1000);
        Opportunity exactHalfOld = oldSide(exactHalfId, 1000);
        Opportunity increaseOld = oldSide(increaseId, 1000);
        Opportunity nullOldOld = oldSide(nullOldId, null);

        List<Opportunity> triggerNew = new List<Opportunity>{
            badNew, exactHalfNew, increaseNew, nullOldNew
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            badOld, exactHalfOld, increaseOld, nullOldOld
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        // Only the record that breaks the rule is rejected...
        assertRejected(badNew, 'only the > half reduction must be rejected');
        // ...everything else in the same call stays clean.
        assertAccepted(exactHalfNew, 'the exact half reduction must not be rejected');
        assertAccepted(increaseNew, 'the increase must not be rejected');
        assertAccepted(nullOldNew, 'the record with a null previous Amount must not be rejected');

        // Exactly one record in this call carries an error.
        Integer recordsWithErrors = 0;
        for (Opportunity opp : triggerNew) {
            if (opp.hasErrors()) {
                recordsWithErrors++;
            }
        }
        Assert.areEqual(1, recordsWithErrors, 'Exactly one record of four must carry an error.');

        // The old side must remain untouched for every record.
        for (Opportunity opp : triggerOld) {
            assertAccepted(opp, 'a trigger.old record must never carry an error');
        }
    }
}
