/**
 * Trigger action (Trigger Actions Framework) for Contact, registered for both contexts by:
 *
 *   Trigger_Action__mdt TA_Contact_PreventDuplicateEmail_BI (Before_Insert__c = Contact, Order 10)
 *   Trigger_Action__mdt TA_Contact_PreventDuplicateEmail_BU (Before_Update__c = Contact, Order 10)
 *
 * Business rule: two Contacts of the same Account may never share an Email address,
 * compared case-insensitively. Contacts without an Account and Contacts without an Email
 * are never evaluated.
 *
 * Behaviour
 *  - Insert: every qualifying Contact is evaluated. Within a single save the first Contact
 *    that claims an account/email key is accepted and each later one receives a record level
 *    error, so valid Contacts in the same save are untouched (partial save still works).
 *  - Update: only Contacts whose Email or AccountId actually changed are evaluated, so
 *    pre-existing (legacy) duplicates never block unrelated edits, and a Contact never
 *    conflicts with itself - the stored value of every evaluated record is dropped from the
 *    conflict set before validation (it is about to be overwritten in this same transaction).
 *  - Bulk safe: at most one SOQL query per trigger execution (none at all when there is
 *    nothing to evaluate), no DML, no nested loops over the database, safe for 200 records.
 *
 * Declared "without sharing" on purpose: this is data integrity enforcement, so duplicate
 * detection must not be silently weakened by the running user's record visibility.
 */
public without sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_ERROR =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforce((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        enforce((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private static void enforce(List<Contact> newContacts, List<Contact> oldContacts) {
        if (newContacts == null || newContacts.isEmpty()) {
            return;
        }

        // 1 - Decide which records are in scope and collect the accounts to query.
        List<Boolean> mustCheck = new List<Boolean>();
        List<String> keys = new List<String>();
        Set<Id> accountIds = new Set<Id>();
        Integer recordsToCheck = 0;

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact current = newContacts[i];
            Boolean check = current.AccountId != null && String.isNotBlank(current.Email);

            // On update only records whose Email or AccountId changed are validated.
            if (check && oldContacts != null) {
                Contact previous = oldContacts[i];
                check = (current.Email != previous.Email)
                    || (current.AccountId != previous.AccountId);
            }

            mustCheck.add(check);
            if (check) {
                keys.add(makeKey(current));
                accountIds.add(current.AccountId);
                recordsToCheck++;
            } else {
                keys.add(null);
            }
        }

        if (recordsToCheck == 0) {
            // Nothing to validate - not a single SOQL query is spent.
            return;
        }

        // 2 - One query for the whole trigger execution: every Contact already stored on the
        //     accounts involved (the email lookup has to be done in Apex because it has to be
        //     case insensitive).
        Map<String, Set<Id>> keyToContactIds = new Map<String, Set<Id>>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ]) {
            String existingKey = makeKey(existing);
            if (!keyToContactIds.containsKey(existingKey)) {
                keyToContactIds.put(existingKey, new Set<Id>());
            }
            keyToContactIds.get(existingKey).add(existing.Id);
        }

        // 3 - The stored value of an evaluated record is overwritten by this same transaction:
        //     remove its own Id from the conflict set so a record never conflicts with itself
        //     and so the key a record is moving away from becomes available again.
        if (oldContacts != null) {
            for (Integer i = 0; i < newContacts.size(); i++) {
                if (!mustCheck[i] || newContacts[i].Id == null) {
                    continue;
                }
                Contact previous = oldContacts[i];
                if (previous.AccountId == null || previous.Email == null) {
                    continue;
                }
                String previousKey = makeKey(previous);
                Set<Id> storedIds = keyToContactIds.get(previousKey);
                if (storedIds != null) {
                    storedIds.remove(newContacts[i].Id);
                    if (storedIds.isEmpty()) {
                        keyToContactIds.remove(previousKey);
                    }
                }
            }
        }

        // 4 - Validate in list order: the first record claiming a key keeps it, every later
        //     record sharing that key is rejected. Records that were not evaluated (unchanged
        //     on update) still reserve their stored key, so they can never be duplicated.
        Set<String> acceptedKeys = new Set<String>();
        for (Integer i = 0; i < newContacts.size(); i++) {
            if (!mustCheck[i]) {
                continue;
            }
            String key = keys[i];
            Set<Id> conflictingIds = keyToContactIds.get(key);
            Boolean duplicate = acceptedKeys.contains(key)
                || (conflictingIds != null && !conflictingIds.isEmpty());

            if (duplicate) {
                newContacts[i].addError(DUPLICATE_EMAIL_ERROR);
            } else {
                acceptedKeys.add(key);
            }
        }
    }

    private static String makeKey(Contact record) {
        return String.valueOf(record.AccountId)
            + '|'
            + String.valueOf(record.Email).toLowerCase();
    }
}
