 * Account trigger record used by TAF entry criteria evaluation.
 *
 * The framework instantiates this class (named in
 * sObject_Trigger_Setting__mdt.TriggerRecord_Class_Name__c), populates the
 * inherited newSobject / oldSobject values for the record being processed, and
 * then evaluates Trigger_Action__mdt.Entry_Criteria__c against it.
 *
 * The typed accessors below give the entry criteria field-level access to both
 * the new and the previous Account value, e.g.:
 *
 *   newRecord.Rating = 'Hot' && oldRecord.Rating != 'Hot'
 *
 * This class is shared by every Account action; actions with a blank
 * Entry_Criteria__c are unaffected by it, so inserts and unrelated updates keep
 * working exactly as before.
 */
public with sharing class AccountTriggerRecord extends TriggerRecord {
    public Account newRecord {
        get {
            return (Account) newSobject;
        }
        set {
            newSobject = value;
        }
    }

    public Account oldRecord {
        get {
            return (Account) oldSobject;
        }
        set {
            oldSobject = value;
        }
    }
}
