public with sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
	/**
	 * Normalizes contact information on every Lead in the before-insert context so the
	 * cleaned values are committed with the original save (no extra DML, no SOQL).
	 *
	 * - Email:     leading/trailing whitespace removed and lower-cased; null stays null.
	 * - Company:   leading/trailing whitespace removed.
	 * - LeadSource: defaulted to 'Web' when blank; an existing value is preserved.
	 *
	 * Bulk-safe: a single in-memory loop over triggerNew with no DML or SOQL,
	 * so 200 leads in one insert are handled in one pass.
	 */
	public void beforeInsert(List<SObject> triggerNew) {
		if (triggerNew == null || triggerNew.isEmpty()) {
			return;
		}

		for (SObject record : triggerNew) {
			Lead lead = (Lead) record;

			if (lead.Email != null) {
				lead.Email = lead.Email.trim().toLowerCase();
			}

			if (lead.Company != null) {
				lead.Company = lead.Company.trim();
			}

			if (String.isBlank(lead.LeadSource)) {
				lead.LeadSource = 'Web';
			}
		}
	}
}
